import * as Phaser from "phaser";

import { flow } from "../flow";

const ROOT = "/assets/mailxp";

/**
 * Loads every Phase 3 asset, forces nearest-neighbor filtering on all textures,
 * then hands off to `flow.afterPreload` (Title in the game, AssetPreview on the
 * /preview route).
 *
 * Frame layouts (authoritative: ASSET_GUIDE.md and processed/manifest.json):
 * - worker.png: exact 4 x 4 grid of 313 x 313 frames (last 2 px unused)
 * - interact-directions.png: exact 4 x 543 x 724 frames
 * - grid/irregular atlases: named frames from processed/*.json generated by
 *   scripts/generate-assets.ps1 (never guessed at runtime)
 */
export class PreloadScene extends Phaser.Scene {
  public constructor() {
    super("Preload");
  }

  public preload(): void {
    // --- exact grids, straight from the asset guide ---
    this.load.spritesheet("worker", `${ROOT}/characters/player/worker.png`, {
      frameWidth: 313,
      frameHeight: 313,
    });
    this.load.spritesheet("worker-interact", `${ROOT}/characters/player/interact-directions.png`, {
      frameWidth: 543,
      frameHeight: 724,
    });

    // --- atlases with measured/named frames (processed/ JSONs) ---
    this.load.atlas("office-npcs", `${ROOT}/characters/npcs/office-npcs.png`, `${ROOT}/processed/office-npcs.json`);
    this.load.atlas("ai-workers", `${ROOT}/characters/agents/ai-workers.png`, `${ROOT}/processed/ai-workers.json`);
    this.load.atlas("mail-bird", `${ROOT}/effects/mail-bird.png`, `${ROOT}/processed/mail-bird.json`);
    this.load.atlas("office-props", `${ROOT}/office/office-props.png`, `${ROOT}/processed/office-props.json`);
    this.load.atlas("mail-effects", `${ROOT}/items/mail-effects.png`, `${ROOT}/processed/mail-effects.json`);

    // --- Phase 6 shop: decor atlases (measured by scripts/measure-shop-assets.ps1) ---
    this.load.atlas("shop-decor", `${ROOT}/shop/decor/shop-decor.png`, `${ROOT}/processed/shop-decor.json`);
    this.load.atlas("shop-wall", `${ROOT}/shop/decor/shop-wall-decor.png`, `${ROOT}/processed/shop-wall.json`);
    this.load.atlas("shop-plants", `${ROOT}/shop/decor/shop-plants-rugs.png`, `${ROOT}/processed/shop-plants.json`);
    this.load.atlas("shop-desk", `${ROOT}/shop/decor/shop-desk-lounge.png`, `${ROOT}/processed/shop-desk.json`);

    // --- Phase 6 outfits: exact 4 x 4 / 313 px sheets like worker.png ---
    for (const key of ["courier", "tech", "forest"]) {
      this.load.spritesheet(`outfit-${key}`, `${ROOT}/shop/outfits/worker-${key}.png`, {
        frameWidth: 313,
        frameHeight: 313,
      });
    }

    // --- regular 32 x 32 tile sheet (nearest-neighbor from selected cells) ---
    this.load.spritesheet("office-tiles", `${ROOT}/processed/office-tiles-32.png`, {
      frameWidth: 32,
      frameHeight: 32,
    });

    // --- machine-readable manifest: every source rect -> output name ---
    this.load.json("manifest", `${ROOT}/processed/manifest.json`);
  }

  public create(): void {
    this.applyNearestFilter();
    this.verifyAtlases();
    this.scene.start(flow.afterPreload);
  }

  /**
   * Fail loudly in the console if an atlas ended up with no named frames — that
   * is the exact symptom of Phaser's addAtlas() rejecting the JSON shape (it
   * warns "missing 'frames' Object" and registers zero frames), and the art
   * silently disappears while everything else looks fine.
   */
  private verifyAtlases(): void {
    for (const key of [
      "office-npcs",
      "ai-workers",
      "mail-bird",
      "office-props",
      "mail-effects",
      "shop-decor",
      "shop-wall",
      "shop-plants",
      "shop-desk",
    ]) {
      const named = this.textures.exists(key) ? this.textures.get(key).getFrameNames().length : 0;
      if (named === 0) {
        console.error(
          `[MailXP] atlas '${key}' registered 0 named frames — processed/${key}.json must be ` +
            `{ "frames": [ { "filename": ... } ] } (Phaser 3.90 addAtlas() dispatch)`,
        );
      }
    }

    // Phase 6 outfit sheets must present the same 16-frame 4 x 4 grid as
    // worker.png, or the walk/idle animations would play on wrong frames.
    for (const key of ["outfit-courier", "outfit-tech", "outfit-forest"]) {
      const frames = this.textures.exists(key) ? this.textures.get(key).frameTotal - 1 : 0;
      if (frames !== 16) {
        console.error(`[MailXP] outfit sheet '${key}' has ${frames} frames — expected 16 (4 x 4 of 313 px)`);
      }
    }
  }

  /** Pixel-art assets must never be smoothed (asset guide: NEAREST filtering). */
  private applyNearestFilter(): void {
    const skip = new Set(["__DEFAULT", "__MISSING", "__WHITE"]);
    for (const key of this.textures.getTextureKeys()) {
      if (skip.has(key)) continue;
      this.textures.get(key).setFilter(Phaser.Textures.FilterMode.NEAREST);
    }
  }
}
